calls.reply:
  "name": "Deep Etching",
  "aka": [],
  "facts": [
    {
      "category": "general",
      "text": "Deep Etching is the practice of inscribing rune symbols into metal surfaces by first bathing a chisel in corrosive acid, then pressing and dragging it across the metal in a controlled stroke.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The acid eats into the metal's grain, leaving the carved rune permanently embedded as a physical feature of the surface, not merely a marking on top of it.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Unlike engraving or stamping, Deep Etching transforms the metal at a molecular level, bonding the rune's resonant frequencies into the material's dormant song.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The acid used varies by region: Ashenmount Academy weavers traditionally favor a distilled solution of mountain celandine, while coastal workshops use black Coralvine extract.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "A Deep Etched rune is considered more durable than one carved by other means, because the acid creates micro-channels that channel ambient Resonance directly into the symbol.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Apprentice weavers typically spend their second year learning Deep Etching before progressing to more advanced techniques like Barkweaving or glass-singing.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The technique requires a steady hand and precise pressure, as too much force can crack the metal and too little leaves a rune too shallow to hold resonance.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Deep Etching is one of the oldest documented techniques in Runeweaving, with early examples found on the boundary stones of the original Ashenmount settlements dating to around the 5th century.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Valdenmark Ruins contain Deep Etched panels that survived the burning of 602, demonstrating the technique's remarkable permanence even under extreme heat.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Master Weavers can Deep Etch runes onto moving metal objects — such as blades or armor in active use — by synchronizing their carving stroke with the object's rhythm of motion.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Third Tenet of Runeweaving is particularly relevant to Deep Etching, as the acid solutions and chisel designs used in the technique are considered freely shareable craft knowledge.",
      "since": null,
      "held_by": null
    }
  ],
  "names": [
