      "kind": "lore",
      "aka": []
    },
    {
      "name": "The Third Tenet",
      "kind": "lore",
      "aka": []
    },
    {
      "name": "The Valdenmark Ruins",
      "kind": "place",
      "aka": []
    },
    {
      "name": "mountain celandine",
      "kind": "item",
      "aka": []
    },
    {
      "name": "black Coralvine extract",
      "kind": "item",
      "aka": []
    }
  ],
  "elsewhere": [
    {
      "entry": "Runeweaving",
      "text": "Deep Etching is one of the foundational techniques taught to Apprentice weavers during their formative years at institutions like Ashenmount Academy.",
      "held_by": null
    },
    {
      "entry": "Ashenmount Academy",
      "text": "Deep Etching is a core curriculum subject at the Academy, with dedicated workshops where apprentices practice on scrap iron before moving to precious metals.",
      "held_by": null
    },
    {
      "entry": "Apprentice",
      "text": "Apprentice weavers must demonstrate proficiency in Deep Etching before they are permitted to advance to intermediate techniques such as Barkweaving.",
      "held_by": null
    },
    {
      "entry": "Master Weaver",
      "text": "Among a Master Weaver's distinguished skills is the ability to perform Deep Etching on moving metal targets, a feat that requires intimate mastery of Resonance and physical control.",
      "held_by": null
    },
    {
      "entry": "The Valdenmark Ruins",
      "text": "Surviving Deep Etched panels within the ruins are studied by Academy scholars as examples of the technique's extraordinary longevity, some still holding faint resonance nearly four centuries after their creation.",
      "held_by": null
    },
    {
      "entry": "The Third Tenet",
      "text": "The Third Tenet's emphasis on free knowledge sharing extends to Deep Etching formulas, which regional workshops exchange openly during annual gatherings at the Keldara Runestone.",
      "held_by": null
    }
  ],
  "move_in": ["M2"]
}


  "name": "Ashenmount Academy",  
  "aka": [  
    {  
      "name": "the Academy",  
      "tag": "common",  
      "everyday": true  
    }  
  ],  
  "facts": [  
    {  
      "category": "description",  
      "text": "Ashenmount Academy is a stone-and-timber institution nestled in a high valley of the Greyveil Mountains, its towers and workshops carved from dark basalt quarried from the surrounding peaks."  
    },  
    {  
      "category": "description",  
      "text": "The Academy's central hall features a vaulted ceiling supported by pillars etched with the Three Tenets of Runeweaving, visible to every apprentice who enters through the great oak doors."  
    },  
    {  
      "category": "description",  
      "text": "Smoke rises year-round from the Academy's foundry district, where Deep Etching workshops operate in long stone buildings arranged around a central courtyard."  
    },  
    {  
      "category": "description",  
      "text": "Apprentices live in dormitories built into the mountainside beneath the main campus, with narrow windows facing the valley below."  
    },  
    {  
      "category": "history",  
      "text": "The original Ashenmount settlement, from which the first Runeweavers emerged, stood on this same site over five centuries ago, though nothing of those early structures survives."  
    },  
    {  
      "category": "history",  
      "text": "The current Academy was commissioned under the Restoration Edict of Queen Thessaly in 988 and has been operational since 992, its curriculum rebuilt from surviving manuscripts and oral traditions."  
    },  
    {  
      "category": "general",  
      "text": "The Academy's library holds one of the largest collections of pre-Burning Runeweaving texts in the known world, including several volumes recovered from the Valdenmark Ruins."  
    },  
    {  
      "category": "general",  
      "text": "Mountain celandine, a pale blue flower that grows only above 4,000 feet in the Greyveils, is cultivated in terraced gardens on the Academy's upper slopes to supply its Deep Etching workshops."  
    },  
    {  
      "category": "general",  
      "text": "The Academy admits apprentices beginning at age fourteen, selected through a written examination and a practical demonstration of manual dexterity."  
    },  
    {  
      "category": "general",  
      "text": "Faculty housing is built into the cliff face north of the campus, with heated stonework that demonstrates the practical Runeweaving skills of the Academy's own graduates."  
    },  
    {  
      "category": "general",  
      "text": "A covered walkway connects the main hall to the foundry district, keeping apprentices out of the harsh mountain winds during the winter months."  
    }  
