"facts": [
  {
    "category": "description",
    "text": "The Temple of the First Changing stands at the exact site in Moskov where Saint Alesander first received divine revelation on the night of the Great Changing in 994.",
    "since": 994
  },
  {
    "category": "description",
    "text": "It is the most sacred shrine of the Church of the Eternal Vigil and the spiritual heart of the Tsardom of Moscavia."
  },
  {
    "category": "description",
    "text": "The temple's architecture combines soaring stone arches with great lantern towers that cast their light outward across the city each night, symbolizing the divine illumination Saint Alesander experienced."
  },
  {
    "category": "description",
    "text": "Its interior is lined with pale birchwood paneling and lit by hundreds of beeswax candles that burn continuously from sundown to sunrise, as the Vigil demands."
  },
  {
    "category": "history",
    "text": "Construction began in 995 under the patronage of the first Tsar of Moscavia, who sought to mark the holy ground where the revelation had occurred."
  },
  {
    "category": "history",
    "text": "The temple was consecrated in 997 and has remained in continuous use as a house of worship and ceremony ever since."
  },
  {
    "category": "law",
    "text": "The Patriarch of Moscavia is required by Church canon and by the Divine Right Doctrine to perform the consecration ceremony of every new Tsar at this temple and nowhere else."
  },
  {
    "category": "law",
    "text": "No secular authority may alter the liturgy or ritual practice of the Temple of the First Changing without the consent of the Ecumenical Council."
  },
  {
    "category": "general",
    "text": "The temple is tended by a permanent clergy of twelve priests and an equal number of acolytes, all of whom have completed the full seven years of nocturnal study mandated by the Vigil."
  },
  {
    "category": "general",
    "text": "On the anniversary of the Great Changing each spring, the temple hosts a solemn pilgrimage service attended by the Tsar, the Patriarch, and thousands of the faithful."
  },
  {
    "category": "general",
    "text": "The site is said to hum with a faint, resonant energy that visitors describe as warmth pressing against the ears — a reminder of the night when God's voice first spoke to Alesander on this very ground."
  },
  {
    "category": "general",
    "text": "The temple's crypt beneath the main nave contains relics attributed to Saint Alesander, including a feather from his final transformation and a fragment of the stone he knelt upon during his revelation."
  }
